# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the session log, a file an AI (or `ds ui debug`) reads to debug what just happened
#          in the app: one JSON line per record in local/logs/ui/ui.jsonl
#          (ds.util.const.UI_LOG_FILE). It holds everything: the outside calls the Alt+D
#          panel shows (logs.py), with their `full` detail, plus what only the file gets
#          (`panel=False`): each chat row as it appeared or changed, each cell run, browser
#          and backend errors, app starts. Kept to MAX_BYTES a file and KEEP files; written
#          as it happens (no queue), so the lines before a crash are there.
# Usage: install() once at import (state.py); State.get_delta calls rows_changed(...);
#        ui.py passes frontend_error / backend_error to rx.App.
# ---------------------------------------------------------------------------
from __future__ import annotations

import dataclasses
import hashlib
import json
import os
import threading
import traceback
from collections import Counter
from pathlib import Path
from typing import Any

from ds.util.const import UI_LOG_FILE
from ds.util.logging import enable_call_logs, for_file, log_event, logger
from reflex.app import default_backend_exception_handler, default_frontend_exception_handler
from reflex.event import EventSpec

MAX_BYTES = 20 * 1024 * 1024  # a file; then it becomes ui.1.jsonl and a new one starts
KEEP = 3  # files in all (ui.jsonl, ui.1.jsonl, ui.2.jsonl): at most 60 MB
# one value in a record (a reply, a cell's output, a response): cut here, so one huge value
# can't fill the file
MAX_VALUE_CHARS = 20_000
APP = "delulu-smash"

# What makes a chat row or a cell "the same as before": the text the user sees, not how it is
# drawn (open / folded, its view, its styled traceback).
CHAT_FIELDS = ("kind", "key", "name", "status", "text", "error", "detail")
CELL_FIELDS = ("id", "count", "code", "stdout", "text", "error")


class RotatingFile:
    """Appends lines to `path`; past max_bytes the file becomes `<stem>.1<suffix>` (older
    ones move up, the oldest is dropped) and a new one starts.
    """

    def __init__(self, path: Path, max_bytes: int = MAX_BYTES, keep: int = KEEP) -> None:
        self.path = path
        self.max_bytes = max_bytes
        self.keep = keep
        self._lock = threading.Lock()

    def older(self, n: int) -> Path:
        return self.path.with_name(f"{self.path.stem}.{n}{self.path.suffix}")

    def write(self, line: str) -> None:
        with self._lock:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            if self.path.exists() and self.path.stat().st_size + len(line) > self.max_bytes:
                for n in range(self.keep - 1, 0, -1):
                    source = self.older(n - 1) if n > 1 else self.path
                    if source.exists():
                        source.replace(self.older(n))
            with self.path.open("a", encoding="utf-8") as file:
                file.write(line)


def _cut(value: Any) -> Any:
    if isinstance(value, str) and len(value) > MAX_VALUE_CHARS:
        return f"{value[:MAX_VALUE_CHARS]}… ({len(value):,} characters in all)"
    return value


def line_of(record: Any) -> str:
    """A loguru record as the file's JSON line: when, level, then the record's fields."""
    fields = {name: _cut(value) for name, value in for_file(record["extra"]).items()}
    row = {"time": record["time"].isoformat(timespec="milliseconds"), "level": record["level"].name} | fields
    return json.dumps(row, default=str, ensure_ascii=False) + "\n"


_installed = False


def install(path: Path | None = None) -> None:
    """Write every record to the session log from now on (once per process), and note the
    start, so a restart shows in the timeline. Nothing is written under pytest unless a path
    is given: a test run must not fill the real log.
    """
    global _installed  # noqa: PLW0603  # one log file per process
    if _installed or (path is None and "PYTEST_VERSION" in os.environ):
        return
    _installed = True
    file = RotatingFile(path or UI_LOG_FILE)

    def sink(message: Any) -> None:
        file.write(line_of(message.record))

    enable_call_logs()
    logger.add(sink, level="INFO", filter=lambda r: "kind" in r["extra"], enqueue=False)
    log_event("app", APP, name="start", panel=False, pid=os.getpid())


# -- chat rows and cells: logged when what they show changes ---------------------------------

# session -> the rows already logged (each by its digest, with how many times it is there)
_seen: dict[str, Counter[str]] = {}
_seen_lock = threading.Lock()


def _fields(item: Any, names: tuple[str, ...]) -> dict[str, str]:
    row = dataclasses.asdict(item) if dataclasses.is_dataclass(item) and not isinstance(item, type) else dict(item)
    return {name: str(row.get(name) or "") for name in names}


def _digest(what: str, fields: dict[str, str]) -> str:
    """A short id of a row's content, the same across restarts (unlike hash())."""
    return hashlib.blake2b(json.dumps([what, fields]).encode(), digest_size=8).hexdigest()


def rows_changed(session: str, chat: list[Any], cells: list[Any]) -> None:
    """Log the chat rows and run cells that are new, or show something else than when last
    logged (an "/assign" row going from asking to proposed to done is three lines).

    Called with the lists as they are being sent to the browser (State.get_delta), so every
    way a row gets there is covered, with nothing to remember at each place that adds one.
    After a backend restart the rows a session already had are logged once more, marked
    `resent` (this process can't know they were): `ds ui debug` leaves those out.
    """
    rows = [("chat", _fields(item, CHAT_FIELDS)) for item in chat]
    # a cell is logged once it ran (its In[n] number), not while typed in
    rows += [("cell", fields) for cell in cells if (fields := _fields(cell, CELL_FIELDS))["count"].isdigit()]
    digests = [_digest(what, fields) for what, fields in rows]
    now = Counter(digests)
    with _seen_lock:
        first_sight = session not in _seen
        before = _seen.get(session, Counter())
        _seen[session] = now
    left = Counter(before)
    for (what, fields), digest in zip(rows, digests, strict=True):
        if left[digest] > 0:
            left[digest] -= 1
            continue
        shared = {"panel": False, "session": session, "digest": digest} | ({"resent": True} if first_sight else {})
        shown = {name: value for name, value in fields.items() if value and name != "kind"}
        if what == "chat":
            log_event("chat", fields["kind"], **shared, **shown)
        else:
            shown["name"] = f"In [{shown.pop('count')}]"
            log_event("cell", "python", **shared, slot=f"cell:{shown.pop('id')}", **shown)
    gone = sum(left.values())
    if gone and not any(what == "chat" for what, _ in rows) and any(before.values()):
        log_event("chat", "cleared", panel=False, session=session, name=f"{gone} rows removed")


def forget() -> None:
    """Forget what was logged for every session (tests)."""
    with _seen_lock:
        _seen.clear()


# -- errors nothing else records -------------------------------------------------------------


def frontend_error(exception: Exception) -> None:
    """A JavaScript error the browser reported (rx.App's frontend_exception_handler): logged,
    then handled as Reflex does (printed to the service's journal).
    """
    text = str(exception).strip()
    log_event("error", "browser", panel=False, name=text.splitlines()[0] if text else "?", error=text)
    default_frontend_exception_handler(exception)


def backend_error(exception: Exception) -> EventSpec:
    """An error no event handler caught (rx.App's backend_exception_handler): logged, then
    handled as Reflex does (the "An error occurred" toast, the traceback in the journal).
    """
    text = "".join(traceback.format_exception(exception))
    log_event("error", "backend", panel=False, name=f"{type(exception).__name__}: {exception}", error=text)
    return default_backend_exception_handler(exception)
